function openContext({event,target}){contextTarget=target;const menu=$('asset-menu');menu.hidden=false;const label=!target?'Map actions':target.kind==='house'?target.address:target.kind==='pole'?'Electrical pole':LABELS[target.utility]+' main';let actions='';if(target?.kind==='house')actions='<button id="context-profile">Open customer profile</button><button id="context-visit" '+(!ops?'disabled':'')+'>🚐 Send a field visit</button>';else if(target)actions='<button id="context-break" '+(!ops?'disabled':'')+'>🔨 Break '+(target.kind==='pole'?'this pole':'this main')+'</button>';menu.innerHTML=`<div class="context-heading">${escape(label)}</div>${actions}<p>${!ops?'Engine snapshot · dispatch and incident commands are not connected yet.':target?(ops?.engine?(m2c?.lockedBefore(ops.timeline?.date||ops.date)?`This day is before your last meter-to-cash action (${escape(m2c.lastActionDay())}): map commands are refused.`:'Live engine · right-drag still orbits.'):'Interactive demo · right-drag still orbits.'):'Zoom closer to a pole, house or visible main, then right-click.'}</p><button id="context-close">Close</button>`;menu.style.left=Math.max(8,Math.min(event.clientX,(window.innerWidth||1200)-280))+'px';menu.style.top=Math.max(8,Math.min(event.clientY,(window.innerHeight||800)-230))+'px';$('context-close').onclick=()=>menu.hidden=true;if($('context-profile'))$('context-profile').onclick=()=>{menu.hidden=true;selectHome(town.premises.find(h=>h.id===target.id));};if($('context-visit'))$('context-visit').onclick=()=>sendVisit(target);if($('context-break'))$('context-break').onclick=async()=>{try{menu.hidden=true;if(mapLocked())return;ops.time=simSeconds;await ops.breakAsset(target);updateFlow();renderOperations(true);$('operations-panel').hidden=false;startPlayback();toast(ops.engine?(target.kind==='pole'?'Pole down: protection tripped. The engine dispatches a crew once the outage is detected.':'Main broken: it leaks until a crew isolates it. The engine dispatches one once it is detected.'):target.kind==='pole'?'Pole damaged. Dispatch a repair crew from Field operations.':'Main damaged. Dispatch a repair crew from Field operations.');}catch(e){toast(e.message);}};}
// A reading round's meter-to-cash outcomes so far (the map shows them as discs at each house).
function readTally(job,t){const n={done:0,read:0,flagged:0,missed:0};for(const s of job.stops||[]){if(s.at>t)break;n.done++;if(n[s.outcome]!=null)n[s.outcome]++;}return n;}
// The linked meter-to-cash run's day: when each step happens and how many houses it touches (rings on the map).
function cycleMarkup(c){if(!c||!Object.keys(c).length)return '';const hm=s=>`${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}`,row=(at,color,text)=>`<div class="detail-line"><span><span class="dot" style="background:${color}"></span>${hm(at)}</span><span>${text}</span></div>`;
 return `<article class="operation-card cycle-card"><strong>Meter-to-cash today</strong>${c.ami?row(c.ami.at,'#4aa3c7',`${fmt(c.ami.read.length)} house${c.ami.read.length===1?'':'s'} read by AMI${c.ami.missed.length?` · <b style="color:#b8433a">${fmt(c.ami.missed.length)} missed</b>${c.ami.dark?` <small>(${fmt(c.ami.dark)} in today's outage)</small>`:''}`:''}`):''}${c.vee?row(c.vee.at,'#e2a43a',c.vee.flagged.length?`VEE flags ${fmt(c.vee.flagged.length)} house${c.vee.flagged.length>1?'s':''}`:'VEE batch: nothing flagged'):''}${c.bills?row(c.bills.at,'#4f9d5d',`${fmt(c.bills.premiseIds.length)} houses billed`):''}${c.invoices?row(c.invoices.at,'#7d6bb3',`${fmt(c.invoices.premiseIds.length)} invoices`):''}<small>Rings appear over the houses at each step.</small></article>`;}
// An empty operations list says when the day's first job starts (a reading round at 08:00), not "no jobs".
function upcoming(jobs,time){const j=nextJob(jobs,time),t=j?((j.startAt%86400)+86400)%86400:0;return j?`No jobs yet. ${escape(JOB_LABEL(j))} start${/s$/.test(JOB_LABEL(j))?'':'s'} at ${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t%3600/60)).padStart(2,'0')}.`:TOUCH?'No jobs yet today.':'No jobs yet. Right-click a house and send your first van.';}
function readTallyMarkup(n){return `<small class="read-tally"><span class="dot read"></span>${n.read} read <span class="dot flagged"></span>${n.flagged} flagged by VEE <span class="dot missed"></span>${n.missed} missed</small>`;}
function renderOperations(force=false){if(!$('operations-body'))return;if(!ops){$('operations-body').innerHTML='<p class="small-note">This is an engine snapshot. Crew trajectories and incident commands will come from the engine; local demo actions are disabled.</p>';$('ops-export').disabled=true;$('ops-reset').disabled=true;return;}$('ops-export').disabled=false;$('ops-reset').disabled=false;$('ops-date').disabled=!ops.engine;$('ops-date').value=ops.timeline?.date||'';$('ops-export').textContent=ops.engine?'Export engine run':'Export demo actions';$('ops-reset').textContent=ops.engine?'Reset engine run':'Reset demo actions';const incidents=ops.incidents.filter(i=>i.createdAt<=ops.time),jobs=ops.jobs.filter(j=>j.startAt<=ops.time),key=incidents.map(i=>i.id+ops.active(i)+i.jobId+(i.isolatedAt!=null&&i.isolatedAt<=ops.time)).join()+'|'+jobs.map(j=>j.id+ops.jobState(j).status+(j.stops?readTally(j,ops.time).done:'')).join();if(!force&&key===ops.uiKey)return;ops.uiKey=key;$('operations-body').innerHTML=`<p class="small-note">${ops.engine?'Engine run':'Browser demo'} · ${simSpeed}× clock. ${TOUCH?'':'Right-click a house for a visit, or a pole/main to break it.'}${ops.engine&&m2c?' Outages feed the worklists: lost use, AMI last gasps, missed reads.':''}${ops.error?' <strong>'+escape(ops.error)+'</strong>':''}</p>${cycleMarkup(ops.timeline?.meterToCash)}${!incidents.length&&!jobs.length?`<div class="billing-empty">${upcoming(ops.jobs,ops.time)}</div>`:''}${incidents.map(i=>`<article class="operation-card"><strong>${escape(i.kind.replaceAll('_',' '))}</strong><span class="operation-status">${ops.active(i)?i.jobId?'Repair assigned':'Awaiting dispatch':'Restored'}</span><small>${escape(i.assetId)}</small>${i.unsupplied||i.utility==='ami'?`<small>${escape(incidentImpact(i,ops.time))}</small>`:''}${i.tie&&i.tie.closedAt<=ops.time&&ops.time<i.tie.openedAt?'<small>Back-fed through a normally-open tie from the next feeder.</small>':''}${ops.active(i)&&!i.jobId?`<button class="outline-btn" data-repair="${i.id}">Dispatch repair crew</button>`:''}</article>`).join('')}${jobs.slice().reverse().map(j=>`<article class="operation-card"><strong>${escape(JOB_LABEL(j))}</strong><span class="operation-status">${escape({en_route:'Driving to site',on_site:'On site · working',returning:'Returning to depot',completed:'Completed'}[ops.jobState(j).status])}</span><small>${escape(j.label||j.targetId)} · ${fmt(j.routeLength)} m by road${j.walkLength?` · ${fmt(j.walkLength)} m round`:''}</small>${j.stops?.some(s=>s.outcome)?readTallyMarkup(readTally(j,ops.time)):''}${ops.jobState(j).status!=='completed'?`<button class="outline-btn" data-follow-job="${j.id}">Follow van</button>`:''}</article>`).join('')}`;document.querySelectorAll('[data-repair]').forEach(btn=>btn.onclick=()=>{const i=ops.incidents.find(i=>i.id===btn.dataset.repair);sendVisit({id:i.assetId,x:i.x,z:i.z},i);});document.querySelectorAll('[data-follow-job]').forEach(btn=>btn.onclick=()=>scene.followJob(ops.jobs.find(j=>j.id===btn.dataset.followJob)));}
